-- Coach — full Chicago Marathon build (Jun 29 -> Oct 11, 2026). Idempotent.
-- Generated. Easy = HR-capped aerobic; MP ~5:15/km; threshold ~5:00; VO2 ~4:35.
on conflict (day_date, session_type) do update set
  title = excluded.title, planned_distance_km = excluded.planned_distance_km,
  planned_duration_min = excluded.planned_duration_min, target_pace = excluded.target_pace,
  details = excluded.details, coach_note = excluded.coach_note;
